static int ct_shim_ambiguity(struct frontend_module_Module * m, const struct frontend_module_Unit * units, int n) {
    int i;
    int j;
    for (i = 0; i < n; i++) {
        if ((!units[i].has_shim)) {
            continue;
        }
        for (j = (i + 1); j < n; j++) {
            if ((!units[j].has_shim)) {
                continue;
            }
            if (strcmp(units[i].base, units[j].base) != 0) {
                continue;
            }
            fprintf(stderr, "ctc: shim base name '%s' is ambiguous: %s, %s\n", units[i].base, units[i].path, units[j].path);
            return 1;
        }
    }
    (void)(m);
    return 0;
}
static const char * cycle_file(struct frontend_module_Module * m, int si) {
    int o = m->sym->structs[si].owner;
    if (((((o >= 0) && (o < m->nunits)) && m->units[o].path) && m->units[o].path[0])) {
        return m->units[o].path;
    }
    return m->path;
}
static int cycle_is_builtin_Box(struct frontend_module_Module * m, const char * name) {
    int inst;
    int ti;
    int tn;
    struct frontend_sym_StructInst * ins;
    struct frontend_sym_StructTmpl * tps;
    const char * b = name;
    (void)(m);
    if (((!b) || (!b[0]))) {
        return 0;
    }
    if (strncmp(b, "struct ", 7) == 0) {
        b += 7;
    }
    inst = frontend_sym_ct_inst_find(b);
    if (inst < 0) {
        return 0;
    }
    ins = frontend_sym_ct_insts((&tn));
    if ((!ins)) {
        return 0;
    }
    ti = ins[inst].tmpl_row;
    tps = frontend_sym_ct_tmpls((&tn));
    if (((ti < 0) || (!tps))) {
        return 0;
    }
    return ((strstr(tps[ti].path, "lib/core/Box.h.ct") != 0) || (strstr(tps[ti].path, "lib/std/Box.h.ct") != 0));
}
static int cycle_Box_target(struct frontend_module_Module * m, int si, int fi) {
    const char * t;
    const char * ptype;
    int bx;
    int pi;
    int n;
    int ti;
    t = m->sym->structs[si].fields[fi].type;
    if (strncmp(t, "struct Box_", 11) == 0) {
        t += 7;
    }
    else {
        if (strncmp(t, "Box_", 4) != 0) {
            return (-1);
        }
    }
    if ((!cycle_is_builtin_Box(m, t))) {
        return (-1);
    }
    bx = m->sym->__frontend_sym_symbolops_vptr->find_struct(m->sym, t);
    if (((bx < 0) || (!m->sym->structs[bx].is_inst))) {
        return (-1);
    }
    for (pi = 0; pi < m->sym->structs[bx].nfields; pi++) {
        if (strcmp(m->sym->structs[bx].fields[pi].name, "ptr") == 0) {
            break;
        }
    }
    if (pi >= m->sym->structs[bx].nfields) {
        return (-1);
    }
    t = m->sym->structs[bx].fields[pi].type;
    n = (int)(strlen(t));
    while (((n > 0) && ((t[(n - 1)] == ' ') || (t[(n - 1)] == '\t')))) {
        n--;
    }
    if (((n == 0) || (t[(n - 1)] != '*'))) {
        return (-1);
    }
    n--;
    while (((n > 0) && ((t[(n - 1)] == ' ') || (t[(n - 1)] == '\t')))) {
        n--;
    }
    ptype = runtime_text_ct_intern_len(t, n);
    if ((!ptype)) {
        return (-1);
    }
    t = ptype;
    if (strncmp(t, "struct ", 7) == 0) {
        t += 7;
    }
    else {
        if (strncmp(t, "union ", 6) == 0) {
            t += 6;
        }
    }
    ti = m->sym->__frontend_sym_symbolops_vptr->find_struct(m->sym, t);
    if (ti < 0) {
        return (-1);
    }
    if ((!m->sym->structs[ti].defined)) {
        return (-1);
    }
    if ((m->sym->structs[ti].is_template || m->sym->structs[ti].is_inst)) {
        return (-1);
    }
    return ti;
}
static int cycle_emit(struct frontend_module_Module * m, int a, int b, int c) {
    const char * chain;
    const char * msg;
    const char * file;
    int nodes[3];
    int n;
    int i;
    int mark;
    nodes[0] = a;
    n = 1;
    if (b >= 0) {
        nodes[n++] = b;
    }
    if (c >= 0) {
        nodes[n++] = c;
    }
    chain = "";
    for (i = 0; i < n; i++) {
        chain = tool_sh_ct_scratch_fmt("%s%s%s", chain, (i ? " -> " : ""), m->sym->structs[nodes[i]].name);
    }
    chain = tool_sh_ct_scratch_fmt("%s -> %s", chain, m->sym->structs[a].name);
    mark = (-1);
    for (i = 0; i < n; i++) {
        if (m->sym->structs[nodes[i]].allow_cycle) {
            mark = nodes[i];
            break;
        }
    }
    if (mark >= 0) {
        if ((!m->check_mode)) {
            return 0;
        }
        msg = tool_sh_ct_scratch_fmt("reference cycle suppressed by 'ct: allow-cycle': %s", chain);
        return tool_diag_ct_sem_note(m->sym->structs[mark].line, m->sym->structs[mark].col, msg, cycle_file(m, mark));
    }
    msg = tool_sh_ct_scratch_fmt("potential reference cycle: %s; instances may leak unless the cycle is broken by hand", chain);
    file = cycle_file(m, a);
    return tool_diag_ct_cycle_warn(m->sym->structs[a].line, m->sym->structs[a].col, msg, file);
}
static int module_src_declares_Box(const char * path) {
    FILE * f;
    char line[1024];
    int after_tag = 0;
    int in_block = 0;
    f = fopen(path, "r");
    if ((!f)) {
        return 0;
    }
    while (fgets(line, sizeof(line), f)) {
        const char * p = line;
        while ((*p)) {
            if (in_block) {
                while (((*p) && (!((p[0] == '*') && (p[1] == '/'))))) {
                    p++;
                }
                if ((*p)) {
                    p += 2;
                    in_block = 0;
                }
                continue;
            }
            if (((p[0] == '/') && (p[1] == '/'))) {
                break;
            }
            if (((p[0] == '/') && (p[1] == '*'))) {
                p += 2;
                in_block = 1;
                continue;
            }
            if ((((*p) == '"') || ((*p) == '\''))) {
                char q = (*p);
                p++;
                while (((*p) && ((*p) != q))) {
                    if ((((*p) == '\\') && p[1])) {
                        p++;
                    }
                    p++;
                }
                if ((*p)) {
                    p++;
                }
                continue;
            }
            if ((!((((((*p) >= 'a') && ((*p) <= 'z')) || (((*p) >= 'A') && ((*p) <= 'Z'))) || (((*p) >= '0') && ((*p) <= '9'))) || ((*p) == '_')))) {
                if ((((((*p) != ' ') && ((*p) != '\t')) && ((*p) != '\n')) && ((*p) != '\r'))) {
                    after_tag = 0;
                }
                p++;
                continue;
            }
{
                const char * q = p;
                while (((((((*q) >= 'a') && ((*q) <= 'z')) || (((*q) >= 'A') && ((*q) <= 'Z'))) || (((*q) >= '0') && ((*q) <= '9'))) || ((*q) == '_'))) {
                    q++;
                }
                if ((((size_t)((q - p)) == 6) && (strncmp(p, "struct", 6) == 0))) {
                    after_tag = 1;
                }
                else {
                    if ((((size_t)((q - p)) == 5) && (strncmp(p, "union", 5) == 0))) {
                        after_tag = 1;
                    }
                    else {
                        if ((((size_t)((q - p)) == 4) && (strncmp(p, "enum", 4) == 0))) {
                            after_tag = 1;
                        }
                        else {
                            if (((after_tag && ((size_t)((q - p)) == 3)) && (strncmp(p, "Box", 3) == 0))) {
                                fclose(f);
                                return 1;
                            }
                            after_tag = 0;
                        }
                    }
                }
                p = q;
            }
        }
    }
    fclose(f);
    return 0;
}
static int ct_pkg_ns_clash(struct frontend_module_Module * m, char * * msg, char * * file) {
    const char * ns;
    char * nroot;
    char * nother;
    int i;
    int j;
    (*msg) = (char *)(0);
    (*file) = (char *)(0);
    for (i = 0; i < m->ninc; i++) {
        if ((!frontend_module_ct_pkg_key(m->incdirs[i], "namespace", (&ns)))) {
            continue;
        }
        frontend_module_ct_norm_path(m->incdirs[i], (&nroot));
        for (j = 0; j < i; j++) {
            const char * other;
            if ((!frontend_module_ct_pkg_key(m->incdirs[j], "namespace", (&other)))) {
                continue;
            }
            if (strcmp(ns, other) != 0) {
                continue;
            }
            frontend_module_ct_norm_path(m->incdirs[j], (&nother));
            if (strcmp(nroot, nother) == 0) {
                continue;
            }
            (*msg) = tool_sh_ct_scratch_fmt("package namespace '%s' is declared by two import roots: '%s' and '%s'", ns, m->incdirs[j], m->incdirs[i]);
            (*file) = tool_sh_ct_scratch_fmt("%s/ct.pkg", m->incdirs[i]);
            return 1;
        }
    }
    return 0;
}
